const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={back:'m14 5-7 7 7 7',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Z|m8 12 3 3 5-6',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',home:'m3 10 9-7 9 7|M5 9v12h5v-7h4v7h5V9',calendar:'M5 5h14v16H5z|M8 3v4|M16 3v4|M5 10h14',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z|M4 21v-2a8 8 0 0 1 16 0v2',search:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0Z|m15 15 6 6',pin:'M19 9c0 6-7 12-7 12S5 15 5 9a7 7 0 1 1 14 0Z|M14 9a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z|M12 7v5l3 2',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2L12 17.3 6.4 20.2l1.1-6.2L3 9.6l6.2-.9L12 3Z',chat:'M21 11a8 8 0 0 1-8 8H5l-3 3V11a9 9 0 0 1 19 0Z|M7 10h10|M7 14h6',call:'M5 3h4l2 5-3 2a13 13 0 0 0 6 6l2-3 5 2v4c0 2-3 3-5 2A21 21 0 0 1 3 8c-1-2 0-5 2-5Z',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z|M12 11v6|M12 7v1',camera:'M3 7h4l2-3h6l2 3h4v14H3V7Z|M16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',tool:'M21 3a6 6 0 0 0-7 8L4 21l-3-3L11 8a6 6 0 0 0 8-7l-4 4 4 2 2-4Z',drop:'M12 2S4 11 4 15a8 8 0 0 0 16 0c0-4-8-13-8-13Z',washer:'M4 3h16v19H4z|M4 7h16|M16 14a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z|M7 5h1|M10 5h1',rotate:'M20 7v5h-5|M4 17v-5h5|M5 8a8 8 0 0 1 13-3l2 4|M19 16a8 8 0 0 1-13 3l-2-4',volume:'M4 9h4l5-4v14l-5-4H4V9Z|M17 8a6 6 0 0 1 0 8|M20 5a10 10 0 0 1 0 14',power:'M12 2v10|M6 5a9 9 0 1 0 12 0',download:'M12 3v12|m7 10 5 5 5-5|M4 17v4h16v-4',close:'m6 6 12 12|m6 18 12-12',list:'M9 5h12|M9 12h12|M9 19h12|M3 5h1|M3 12h1|M3 19h1',battery:'M3 7h16v10H3z|M21 10v4|M5 9h11v6H5z',signal:'M4 20v-4|M9 20v-8|M14 20V8|M19 20V4',wifi:'M3 8a15 15 0 0 1 18 0|M6 12a10 10 0 0 1 12 0|M9 16a5 5 0 0 1 6 0|M12 20h.01',file:'M5 3h9l5 5v13H5V3Z|M14 3v5h5|M8 12h8|M8 16h6',money:'M3 5h18v14H3z|M14 12a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z|M6 8h1|M17 16h1'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(paths[name]||paths.info).split('|').map(p=>`<path d="${p}"/>`).join('')}</svg>`;
const button=(text,action,style='',disabled=false)=>`<button class="btn ${style}" data-action="${action}" ${disabled?'disabled':''}>${text}</button>`;
const badge=(text,color='',ico)=>`<span class="badge ${color}">${ico?icon(ico):''}${text}</span>`;
const checks=[['Drain filter inspected','Blocked by lint and debris','Issue found'],['Drain pump output tested','Output below expected range','Issue found'],['Outlet hose inspected','Visible crack near the connector','Issue found'],['Drain pipe checked','No external blockage found','Passed'],['Control-panel error checked','OE drainage error recorded','Issue found'],['Drum rotation tested','Working normally','Passed']];
const evidenceSeed=[{title:'Blocked drain filter',check:0,time:'10:42 AM',description:'Lint and debris are visibly blocking the drain filter.',type:'photo',clear:true},{title:'Damaged outlet hose',check:2,time:'10:46 AM',description:'A visible crack is present near the hose connector.',type:'photo',clear:true},{title:'Pump-output reading',check:1,time:'10:49 AM',description:'Measured flow: 4 L/min. Technician reference range: 8–12 L/min.',limitation:'This reading identifies reduced output but does not independently identify the exact cause.',type:'reading',clear:true},{title:'OE drainage error',check:4,time:'10:52 AM',description:'The control panel displayed the OE drainage error during the inspection.',limitation:'An error code indicates a drainage problem; it does not confirm which component caused it.',type:'code',clear:true}];
const summaryConfirmed='Your washing machine is unable to drain water properly because the drain filter is blocked and the outlet hose is damaged. The pump is still functioning, but its output is below the expected range.';
const summaryLikely='The professional measured reduced pump output. This may indicate reduced pump efficiency, but the cause has not been confirmed. A further test after cleaning is required before deciding whether any pump repair is needed.';
const summaryUnverified='The professional could not reproduce or confirm the reported drainage issue. Additional inspection is required before recommending repair.';
const rules=TrustRules;
const base=()=>({role:'customer',screen:'home',booked:false,submitted:false,customerStatus:'Not viewed',approved:false,repairStarted:false,completed:false,inspectionClosed:false,expert:'none',certainty:'Confirmed',certaintyReason:'Supported by filter inspection, pump-output reading, visible hose damage and recorded drainage error.',recommend:'Repair',checkStatus:['Issue found','Issue found','Issue found','Passed','',''],checkReasons:{},observations:{},evidence:structuredClone(evidenceSeed),summary:'',reviewed:false,quoteCreated:false,prices:[499,600],selected:[true,true],links:[true,true],revised:false,revision:1,approvedRevision:null,history:[],date:'12 Oct',slot:'10:00–11:00 AM',symptoms:[true,true,false,true],service:'Not draining',rating:0,declineReason:'',finishedAt:''});
let state;try{state=rules.load(localStorage.getItem('uc-trust-v1'),base)}catch{state=base()}
let draftEpoch=0;
let mapOpen=false,expanded=new Set(),quoteExpanded=new Set(),sheet=null,assistLanguage='English',assistQuestion=null,busy=false,toastTimer;
function save(){try{localStorage.setItem('uc-trust-v1',JSON.stringify(state))}catch{toast('Storage is full. Your session is still available.')}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function go(screen){state.history.push({screen:state.screen,role:state.role});state.screen=screen;save();render();$('.content')?.scrollTo(0,0)}
function back(){let prev=state.history.pop();while(prev&&prev.role!==state.role)prev=state.history.pop();if(prev){state.screen=prev.screen;save();render()}else go(state.role==='customer'?'home':'assigned')}
const total=()=>rules.total(state);
const hasQuote=()=>rules.repairQuote(state);
const scope=()=>rules.selected(state).map(i=>rules.items[i]).join('<br>');
function checkObservation(i){return state.observations[i]||(state.checkStatus[i]==='Issue found'?(i===3||i===5?'Add an observation describing the abnormal result':checks[i][1]):state.checkStatus[i]==='Could not verify'?state.checkReasons[i]||'Check could not be verified':state.checkStatus[i]==='Passed'?'Check passed; no issue recorded':'Check not completed');}
function findingText(){if(state.certainty==='Confirmed'&&[0,1,2,4].every(i=>rules.evidenceSupports(state,i))&&!Object.keys(state.observations).length&&state.checkStatus[3]==='Passed'&&state.checkStatus[5]==='Passed')return 'Drain filter blockage with reduced pump output and damaged outlet hose.';return state.certainty==='Confirmed'?[0,1,2,3,4,5].filter(i=>state.checkStatus[i]==='Issue found').map(i=>checks[i][0]+': '+checkObservation(i)).join('; ')||'No abnormal finding recorded':state.certainty==='Likely'?([0,1,2,3,4,5].filter(i=>state.checkStatus[i]==='Issue found').map(i=>checks[i][0]+': '+checkObservation(i)).join('; ')+'; cause remains uncertain.'):'The reported issue could not be reproduced or confirmed.';}
function draftSummary(){if(state.certainty==='Confirmed'&&state.recommend==='Repair'&&[0,1,2,4].every(i=>rules.evidenceSupports(state,i))&&!Object.keys(state.observations).length&&state.checkStatus[3]==='Passed'&&state.checkStatus[5]==='Passed')return summaryConfirmed;return state.certainty==='Confirmed'?`Recorded inspection findings: ${findingText()}. Recommendation: ${state.recommend}.`:state.certainty==='Likely'?`Recorded inspection findings: ${findingText()}. Recommendation: ${state.recommend}.`:`The reported issue could not be reproduced or confirmed. Recommendation: ${state.recommend}.`;}
function summaryText(){return state.summary||draftSummary();}
const money=n=>'₹'+Number(n).toLocaleString('en-IN');
const allChecks=()=>rules.allChecks(state);
const validations=()=>rules.validations(state);
const canSubmit=()=>rules.canSubmit(state);
const canRepair=()=>rules.canRepair(state);
function washerArt(){return `<svg class="washer" viewBox="0 0 160 210" aria-label="Front-load washing machine illustration" role="img"><defs><linearGradient id="body" x1="0" x2="1"><stop stop-color="#d8d8db"/><stop offset=".4" stop-color="#fafafb"/><stop offset="1" stop-color="#cfcdd4"/></linearGradient><linearGradient id="glass" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#383740"/><stop offset="1" stop-color="#13131b"/></linearGradient></defs><path d="M23 13 136 20l7 172-121-2Z" fill="#a7a5af"/><rect x="14" y="12" width="121" height="184" rx="7" fill="url(#body)"/><path d="M16 46h116" stroke="#c4c2ca"/><rect x="24" y="24" width="42" height="10" rx="2" fill="#eeeef0" stroke="#b5b2bc"/><circle cx="83" cy="31" r="7" fill="#a5a3ad" stroke="#f6f6f8" stroke-width="3"/><rect x="101" y="25" width="25" height="11" rx="2" fill="#302d38"/><text x="105" y="33" fill="#bfd1cf" font-size="6">0:45</text><circle cx="75" cy="110" r="48" fill="#b7b4bf"/><circle cx="75" cy="110" r="42" fill="#eeeef0"/><circle cx="75" cy="110" r="34" fill="url(#glass)"/><path d="M50 90q20-16 44 7l-5 33q-29 12-39-7Z" fill="#77727e" opacity=".5"/><path d="M48 89q19-19 42-7" fill="none" stroke="#fff" stroke-width="3" opacity=".25"/><rect x="23" y="174" width="102" height="4" rx="2" fill="#b8b6bf"/><rect x="101" y="156" width="23" height="12" rx="3" fill="#dad8df" stroke="#c4c1cb"/></svg>`}
function avatar(){return `<div class="avatar"><svg viewBox="0 0 48 48" role="img" aria-label="Arjun Kumar illustrated profile"><rect width="48" height="48" fill="#eee4d8"/><path d="M6 48c0-13 10-20 18-20s18 7 18 20" fill="#484458"/><path d="m20 28-1 7 5 4 6-4-2-8" fill="#bc886b"/><ellipse cx="24" cy="19" rx="10" ry="13" fill="#cc9b7a"/><path d="M14 17V9c2-7 18-7 20 2v6l-5-8c-4 4-8 4-15 5Z" fill="#302827"/><path d="M16 23c2 8 13 9 16-1l-4 4h-8Z" fill="#5b3d32"/><path d="M20 18h1m7 0h1" stroke="#302827" stroke-width="2" stroke-linecap="round"/></svg></div>`}
function evidenceArt(e){if(e.url&&e.type==='video')return `<video src="${esc(e.url)}" controls playsinline aria-label="${esc(e.title)}" style="width:100%;height:100%;object-fit:contain"></video>`;if(e.url)return `<img src="${esc(e.url)}" alt="${esc(e.title)}">`;let art='';if(e.type==='reading')art=`<rect width="180" height="110" fill="#e5e8e6"/><rect x="44" y="12" width="94" height="93" rx="10" fill="#414b43"/><rect x="52" y="23" width="78" height="43" rx="4" fill="#d4ddc7"/><text x="91" y="44" text-anchor="middle" font-family="monospace" font-size="18" fill="#354638">4.0</text><text x="91" y="58" text-anchor="middle" font-size="8" fill="#45553e">L / MIN</text><circle cx="70" cy="82" r="8" fill="#e0a34a"/><circle cx="108" cy="82" r="8" fill="#859079"/>`;else if(e.type==='code')art=`<rect width="180" height="110" fill="#c8c6c9"/><path d="M0 26h180v57H0" fill="#e1e0e3"/><rect x="32" y="35" width="115" height="40" rx="4" fill="#26252b"/><text x="88" y="65" text-anchor="middle" font-family="monospace" font-size="31" fill="#b8d2b8">OE</text><circle cx="14" cy="55" r="9" fill="#aaa7b0"/>`;else if(e.check===2)art=`<rect width="180" height="110" fill="#b6b5ad"/><path d="M-10 89c47-11 83-76 113-44s35 8 84 0" fill="none" stroke="#777a72" stroke-width="27"/><path d="M-10 89c47-11 83-76 113-44s35 8 84 0" fill="none" stroke="#a5a79d" stroke-width="22" stroke-dasharray="3 3"/><path d="m100 41 8 15-10 8 12 8" stroke="#45483e" stroke-width="3" fill="none"/><circle cx="105" cy="55" r="23" fill="none" stroke="#f3c374" stroke-width="1.5"/>`;else art=`<rect width="180" height="110" fill="#bebbb1"/><ellipse cx="90" cy="59" rx="57" ry="45" fill="#555851"/><ellipse cx="90" cy="59" rx="46" ry="34" fill="#898c79"/><path d="m56 50 54 28M53 61l54-17M68 32l16 58M100 32 91 87" stroke="#454c3c" stroke-width="5"/><path d="m61 44 23 13 28-11-4 22-30 7-21-14Z" fill="#6c604b"/><path d="m64 48 17 3 12 16m-20-7 34-4" fill="none" stroke="#b1a07b" stroke-width="4"/><circle cx="90" cy="58" r="32" fill="none" stroke="#f3c374" stroke-width="1.5"/>`;return `<svg viewBox="0 0 180 110" role="img" aria-label="Illustrative demo: ${esc(e.title)}">${art}</svg>`}
function profile(){return `<div class="row profile">${avatar()}<div class="grow"><h3>Arjun Kumar ${badge('UC verified','green','shield')}</h3><div class="small">${icon('star')} <b>4.82</b> <span class="muted"> · 1,240 jobs completed</span></div></div></div>`}
function assistCard(quote=false){return `<div class="card purple assist"><div class="assist-header">${icon('spark')}${quote?'UC Assist quotation explanation':'Explained with UC Assist · Simulated draft'}</div><p>${esc(summaryText())}</p>${quote?`<p>Selected scope:<br>${scope()}</p>`:''}<p class="tiny muted">Recorded certainty: ${esc(state.certainty)} · Recommendation: ${esc(state.recommend)}. The professional owns the diagnosis; UC Assist explains recorded findings in this browser.</p><div class="reviewed">${icon('shield')} ${state.reviewed?'Reviewed by Arjun Kumar':'Draft awaiting professional review'}</div></div>`}
function evidenceCards(){return `<div class="evidence-grid">${state.evidence.map((e,i)=>`<button class="evidence-card" data-action="evidence:${i}"><div class="evidence-art">${evidenceArt(e)}</div><div class="evidence-copy"><b>${esc(e.title)}</b><span>${esc(e.time)} · By Arjun</span><span>${esc(checks[e.check][0])}</span><span class="link">View evidence ${icon('chevron')}</span></div></button>`).join('')}</div>`}
function clarificationCard(){return state.clarification?`<div class="card"><h3>Professional clarification</h3><p>${esc(state.clarification)}</p></div>`:'';}
function findingCard(){return `<div class="card ${state.certainty==='Confirmed'?'green':'amber'} finding"><div class="row between"><span class="eyebrow">Overall finding</span><button data-action="certainty-info">${badge(state.certainty,state.certainty==='Confirmed'?'green':'amber','info')}</button></div><h3>${esc(findingText())}</h3><p>${esc(state.certaintyReason)}</p><div class="recommend"><div class="tiny muted">RECOMMENDED NEXT STEP</div><p class="bold">${esc(state.recommend)}${hasQuote()?`<br>${scope()}`:''}</p></div></div>`}
function checksCard(){return `<div class="card checks-card">${checks.map((c,i)=>`<div class="check-row"><button data-action="expand:${i}" aria-expanded="${expanded.has(i)}">${icon('check','check-icon')}<span class="check-text">${c[0]}<small>${esc(state.checkStatus[i]||'Not completed')} · ${esc(checkObservation(i))}</small></span>${icon('chevron','chevron')}</button>${expanded.has(i)?`<div class="check-detail">${esc(checkObservation(i))}. ${state.checkStatus[i]==='Could not verify'?esc(state.checkReasons[i]):'Completed by Arjun Kumar during the inspection.'}<br>${state.evidence.filter(e=>e.check===i).length?'Supporting evidence is available below.':'Recorded as a visual / functional check.'}</div>`:''}</div>`).join('')}</div>`}
function linkedDescription(i){return state.evidence.filter(e=>i===0?[0,1].includes(e.check):e.check===2).map(e=>e.type+': '+e.description).join('; ');}
function quoteItems(edit=false){return rules.items.map((name,i)=>!state.selected[i]? (edit?`<div class="card"><b>${name}</b><p>UC rate card · ${money(state.prices[i])}</p>${button('Add to quotation','item:'+i,'secondary')}</div>`:''):`<div class="card"><div class="row between start"><div class="quote-title">${name}</div>${edit?`<div>₹ <input class="quote-input" type="number" min="1" max="99999" step="1" data-price="${i}" aria-label="${name} price" value="${state.prices[i]}"></div>`:`<div class="price">${money(state.prices[i])}</div>`}</div><div style="margin-top:7px">${badge('UC rate card','purple','shield')}</div><div class="reason">${icon('check')} ${esc(linkedDescription(i))}</div>${edit?`${button('Remove item','item:'+i,'quiet')}<label class="checkbox"><input type="checkbox" data-link="${i}" ${state.links[i]?'checked':''}>Link finding, completed check and ${i===0?'filter photo + pump reading':'hose photo'}</label>`:`<div class="quote-links"><button class="link" data-action="quote-expand:${i}">Why is this needed?</button><button class="link" data-action="linked:${i}">${icon('camera')} View linked evidence</button></div>`}${quoteExpanded.has(i)?`<p class="muted small">${i===0?'The technician will remove accumulated lint and debris, clean the filter and drainage system, and retest water flow. This quote does not include pump replacement.':'The cracked outlet hose will be replaced and the connection checked for leaks. Includes the replacement hose and fitting.'}</p>`:''}<div class="row small muted">${icon('shield')} 30-day service warranty</div></div>`).join('')}
function totals(){return `<div class="card"><div class="info-row"><span>Repair services</span><span>${money(total()-249)}</span></div><div class="info-row"><span>Inspection fee</span><span>₹249</span></div><div class="row between total"><b>Total payable</b><span class="price">${money(total())}</span></div><div class="row between small muted" style="margin-top:12px"><span>${icon('clock')} 45 minutes</span><span>${icon('shield')} 30-day warranty</span></div></div>`}
const step=n=>`<div class="step-indicator">${Array.from({length:6},(_,i)=>`<span class="${i<n?'on':''}"></span>`).join('')}</div><div class="eyebrow">Inspection · Step ${n} of 6</div>`;
let footer='',nav=false;
function page(){footer='';nav=false;const s=state.screen;switch(s){
case 'home':nav=true;footer=button('Continue '+icon('chevron'),'go:select');return `<div class="page white"><div class="search">${icon('search')}<input id="search" aria-label="Search services" placeholder="Search for a service"></div><div class="hero"><div class="hero-copy"><div class="eyebrow" style="color:#7c5caf;letter-spacing:1px">Expert care at home</div><h1>Washing Machine<br>Repair</h1><div class="small muted">Back to laundry.<br>Without the guesswork.</div><div style="margin-top:16px">${badge('★ 4.82 · Trusted professionals','purple')}</div></div>${washerArt()}</div><div class="benefits"><div>${icon('shield')}<br>UC verified<br>professionals</div><div>${icon('money')}<br>Transparent<br>pricing</div><div>${icon('calendar')}<br>30-day service<br>warranty</div></div><div class="row between"><h3 class="section-title">What do you need help with?</h3></div><div class="options-grid">${['Washing machine check-up','Water leakage','Not draining','Not spinning','Unusual noise','Not powering on'].map((t,i)=>`<button class="service-option ${state.service===t?'selected':''}" data-action="service:${i}">${icon(['washer','drop','drop','rotate','volume','power'][i])}<span>${t}</span>${state.service===t?icon('check'):''}</button>`).join('')}</div><div class="home-note">${icon('info')}<span>Check-up starts at <b style="color:#39333f">₹249</b><br>Review the diagnosis and approve the quote before repair.</span></div></div>`;
case 'select':footer=button('Book check-up · ₹249','book');return `<div class="page">${badge('Washing machine repair','purple')}<h1 class="page-title">Tell us a little more</h1><p class="subtitle">A few details help your professional prepare.</p><div class="card"><div class="info-row"><span>Appliance</span><span>Front-load washing machine</span></div><div class="info-row"><span>Brand</span><span>LG</span></div><div class="info-row"><span>Issue</span><span>${esc(state.service==='Not draining'?'Water is not draining':state.service)}</span></div><div class="divider"></div><div class="row between"><span>Inspection charge</span><b>₹249</b></div></div><h3 class="section-title">Anything else you’ve noticed?</h3>${['Water remains inside the drum','Machine displays an error code','Unusual pump noise','Problem started recently'].map((t,i)=>`<label class="checkbox"><input type="checkbox" data-symptom="${i}" ${state.symptoms[i]?'checked':''}>${t}</label>`).join('')}<h3 class="section-title">Choose a convenient visit</h3><div class="chips date-chips">${['12 Oct','13 Oct','14 Oct'].map(t=>`<button class="chip ${state.date===t?'active':''}" data-action="date:${t}">${t==='12 Oct'?'Mon':t==='13 Oct'?'Tue':'Wed'}<br><b>${t}</b></button>`).join('')}</div><div class="chips">${['10:00–11:00 AM','12:00–1:00 PM','3:00–4:00 PM'].map(t=>`<button class="chip ${state.slot===t?'active':''}" data-action="slot:${t}">${t}</button>`).join('')}</div><div class="card purple"><div class="row start">${icon('shield')}<p style="margin:0">The professional will inspect the appliance and share a quotation for your approval before beginning the repair.</p></div></div></div>`;
case 'booking':nav=true;footer=state.submitted?button('Review diagnosis '+icon('chevron'),'go:ready'):button('Mark inspection complete','mark-inspection','secondary');return `<div class="page"><div class="row between">${badge(state.submitted?'Diagnosis ready':'Booking confirmed','green','check')}<span class="tiny muted">UC-WM-28491</span></div><h1 class="page-title" style="margin-top:15px">You’re in good hands</h1><p class="subtitle">LG front-load washing machine · ${esc(state.service)}</p><div class="card">${profile()}<div class="divider"></div><div class="row between small"><span class="muted">${state.submitted?'Inspection complete':'Scheduled arrival'}</span><b>${state.date} · ${state.slot}</b></div><div class="inline-btns" style="margin-top:15px">${button(icon('call')+' Call','contact:call','secondary')}${button(icon('chat')+' Chat','contact:chat','secondary')}</div></div><h3 class="section-title">Your booking, step by step</h3><div class="card timeline">${['Booking confirmed','Professional assigned','Professional arrived','Inspection in progress','Diagnosis ready'].map((t,i)=>`<div class="timeline-step"><span class="dot ${i<(state.submitted?5:3)?'done':i===3&&!state.submitted?'current':''}">${i<(state.submitted?5:3)?icon('check'):''}</span><div><b>${t}</b><div class="tiny muted">${['Your check-up is scheduled','Arjun Kumar is your professional','Professional checked in at 10:35 AM','6 checks to understand the issue','Review the findings before the quote'][i]}</div></div></div>`).join('')}</div><div class="card"><div class="row start">${icon('pin')}<div><b class="small">Service address</b><p>Rahul Mehta<br>Flat 402, Palm Heights, Lokhandwala<br>Andheri West, Mumbai · 400053</p></div></div></div><div class="card purple"><h3>What happens during inspection?</h3><p>Arjun checks the drainage system and records evidence. You’ll see the findings, certainty and an itemised quote before deciding.</p></div>${!state.submitted?'<p class="tiny muted center">Prototype control opens the professional’s required inspection steps.</p>':''}</div>`;
case 'ready':if(!state.submitted)return locked();footer=button('Review diagnosis '+icon('chevron'),'view-diagnosis')+button('Message professional','contact:chat','quiet');return `<div class="page center"><div class="big-success">${icon('check')}</div>${badge('Inspection complete','green')}<h1 class="page-title" style="margin-top:17px">Your diagnosis is ready</h1><p class="subtitle">Arjun has completed 6 diagnostic checks<br>and added supporting evidence.</p><div class="stats" style="text-align:left;margin-top:26px"><div><b>6</b><span>Diagnostic checks completed</span></div><div><b>${state.evidence.length}</b><span>Supporting evidence items</span></div><div><b>1</b><span>${state.certainty.toLowerCase()} finding</span></div><div><b>18 <span>min</span></b><span>Time spent on inspection</span></div></div><div class="card purple" style="text-align:left;margin-top:22px"><div class="row start">${icon('shield')}<p style="margin:0">Understand what was found, see the evidence and choose what happens next. You’re in control.</p></div></div>${profile()}</div>`;
case 'diagnosis':if(!state.submitted)return locked();footer=rules.terminal(state)?button('View service record','go:record','secondary')+button(icon('spark')+' Ask UC Assist','assist','quiet'):hasQuote()?button('View repair quote '+icon('chevron'),'view-quote')+button(icon('spark')+' Ask UC Assist','assist','quiet'):button('Request expert review','expert')+button(icon('spark')+' Ask UC Assist','assist','quiet');return `<div class="page"><div class="row between"><span class="eyebrow">Inspection complete</span>${badge('6 checks · '+state.evidence.length+' evidence items')}</div><h1 class="page-title">Diagnosis Snapshot</h1><p class="subtitle">See what was checked, what was found and how certain the professional is.</p>${findingCard()}${clarificationCard()}${state.certainty!=='Confirmed'?`<div class="card amber"><h3>What we know — and what we don’t</h3><p>${esc(summaryText())}</p><p>Recorded next step: ${esc(state.recommend)}</p><p>No repair quotation is offered for this inspection.</p></div>`:''}<div class="row between"><h3 class="section-title">Checks completed</h3><span class="small muted">6 of 6</span></div>${checksCard()}<div class="row between"><h3 class="section-title">Supporting evidence</h3>${badge('Captured on-site','green','camera')}</div>${evidenceCards()}<div class="trust-note">${icon('info')}<span>Evidence is recorded by your professional. Readings and error codes support the inspection and may not identify the exact cause on their own.</span></div>${assistCard()}<h3 class="section-title">Still have a question?</h3><div class="chips">${['Why does the hose need replacement?','Can I continue using the machine?','What happens if I repair it later?','Show me the supporting evidence'].map((q,i)=>`<button class="chip" data-action="ask:${i}">${q}</button>`).join('')}</div></div>`;
case 'quote':if(!state.submitted||!hasQuote())return locked();footer=button('Continue to decision '+icon('chevron'),'go:decision')+button(icon('spark')+' Ask about this quote','assist','quiet');return `<div class="page"><div class="eyebrow">Your repair plan</div><h1 class="page-title">Repair quotation</h1><p class="subtitle">Every charge is connected to a finding from your diagnosis.</p>${state.revised?`<div class="card amber"><h3>Your quotation has been updated</h3><p>Old total: ${money(state.revisionChange?.oldTotal??total())} · New total: ${money(state.revisionChange?.newTotal??total())}<br><b>Change: ${money((state.revisionChange?.newTotal??total())-(state.revisionChange?.oldTotal??total()))}</b> · ${esc(state.revisionChange?.description||'Updated replacement-part price')}</p><p class="tiny">Your previous approval is no longer valid. Please review and approve this version.</p></div>`:''}${quoteItems()}${totals()}<div class="trust-note">${icon('shield')}<span>Prices follow Urban Company’s service rate card. No additional work will begin without your approval.</span></div>${assistCard(true)}<button class="link" data-action="go:diagnosis">${icon('back')} Back to the Diagnosis Snapshot</button></div>`;
case 'decision':if(!state.submitted||!hasQuote())return locked();footer='<div class="caption">Choose the option that’s right for you. Nothing is preselected.</div>';return `<div class="page"><h1 class="page-title">Choose what happens next</h1><p class="subtitle">Your diagnosis and quote are ready.<br>Take a moment. The decision is yours.</p>${state.revised?'<div class="warning">Updated quote · Fresh approval required</div>':''}<div class="card decision-card"><div class="row"><span class="option-icon">${icon('tool')}</span><h3 style="margin:0">Approve repair</h3></div><p>${scope()}</p><div class="row between"><b>${money(total())}</b><span class="small muted">45 min · 30-day warranty</span></div>${button((state.revised?'Approve revised quote · ':'Approve ')+money(total())+' · v'+state.revision,'approve','secondary',!rules.canApprove(state))}</div><div class="card decision-card"><div class="row"><span class="option-icon">${icon('shield')}</span><h3 style="margin:0">Request expert review</h3></div><p>A senior UC expert reviews the diagnosis, evidence and quotation.</p><div class="small muted">Within 15 minutes · Your professional will wait</div>${button('Request expert review','expert','secondary')}</div><div class="card decision-card"><div class="row"><span class="option-icon">${icon('clock')}</span><h3 style="margin:0">Decline repair</h3></div><p>The appliance will not be repaired. Inspection charges may still apply. Your diagnosis stays in booking history.</p>${button('Decline repair','decline','secondary')}</div></div>`;
case 'expert':footer=state.expert==='complete'?(hasQuote()?button('Approve repair · '+money(total())+' · v'+state.revision,'approve','',!rules.canApprove(state))+button('Speak to expert','contact:expert','secondary')+button('Decline repair','decline','quiet'):button('View recorded recommendation','view-diagnosis','secondary')):button('Complete expert review · Demo','expert-complete','secondary');return `<div class="page center"><div class="big-success" style="background:#eee7ff;color:var(--purple)">${icon('shield')}</div>${badge(state.expert==='complete'?'Review complete':'Expert review requested','purple')}<h1 class="page-title" style="margin-top:16px">${state.expert==='complete'?'A second look. More clarity.':'An expert is taking a look'}</h1><p class="subtitle">${state.expert==='complete'?(state.certainty==='Confirmed'?'The diagnosis and quoted work are supported by the submitted checks and evidence.':'The available evidence does not confirm the cause. Recorded recommendation: '+esc(state.recommend)+'.'):'Your diagnosis is being reviewed by a UC expert.'}</p><div class="card" style="text-align:left"><div class="row">${icon('file')}<b>What’s being reviewed</b></div><div class="record-line">${icon('check')} 6 diagnostic checks</div><div class="record-line">${icon('check')} Supporting evidence and certainty</div><div class="record-line">${icon('check')} Each repair item and its price</div></div><div class="card purple" style="text-align:left"><p>${icon('clock')} ${state.expert==='complete'?'Review completed by UC senior expert Priya Shah.':'Estimated response: within 15 minutes.'}</p><p>Your professional will wait. No repair will start without your approval.</p></div>${clarificationCard()}<p class="tiny muted">Prototype review is simulated and creates no real service request.</p></div>`;
case 'approved':footer=button('View professional’s next step '+icon('chevron'),'switch-tech','secondary');return `<div class="page center"><div class="big-success">${icon('check')}</div>${badge('Repair approved','green')}<h1 class="page-title" style="margin-top:16px">All set, Rahul</h1><p class="subtitle">Arjun has received your approval.<br>He can now begin the agreed repair.</p><div class="card" style="text-align:left"><h3>Approved scope</h3><p>${scope()}</p><div class="divider"></div><div class="row between"><b>Approved amount</b><b class="price">${money(total())}</b></div><div class="info-row"><span>Estimated repair time</span><span>45 minutes</span></div><div class="info-row"><span>Service warranty</span><span>30 days</span></div>${badge('Quote version '+state.revision,'green')}</div><div class="card purple" style="text-align:left"><p>Any change in the scope or price will need your approval again.</p></div>${profile()}</div>`;
case 'declined':footer=button('View booking history','go:record','secondary');return `<div class="page center"><div class="big-success" style="background:#f1eef6;color:#787181">${icon('check')}</div><h1 class="page-title">Your choice is recorded</h1><p class="subtitle">The repair has been declined. Arjun will not begin work.</p><div class="card" style="text-align:left"><h3>Your inspection is still available</h3><p>The Diagnosis Snapshot and evidence remain in your booking history.</p><div class="info-row"><span>Inspection charge</span><span>₹249</span></div><p class="tiny muted">Inspection charges may still apply.</p>${state.declineReason?`<div class="info-row"><span>Your reason</span><span>${esc(state.declineReason)}</span></div>`:''}</div></div>`;
case 'record':if(!state.submitted)return locked();nav=true;footer=button('Book another service','new-booking','secondary');return `<div class="page"><div class="row between">${badge(state.completed?'Repair completed':state.inspectionClosed?'Inspection closed':state.customerStatus==='Declined'?'Repair declined':'Service record',state.completed?'green':'',state.completed?'check':null)}<span class="tiny muted">UC-WM-28491</span></div><h1 class="page-title" style="margin-top:13px">Your service record</h1><p class="subtitle">Everything from this visit, in one place.</p><div class="card"><h3>LG front-load washing machine</h3><p class="muted">${esc(state.service)} · Andheri West, Mumbai</p><div class="divider"></div><div class="tiny muted">FINAL DIAGNOSIS</div><p class="bold">${esc(findingText())}</p><p>Certainty: ${esc(state.certainty)} · ${esc(state.recommend)}</p><button class="link" data-action="go:diagnosis">View diagnostic checks and evidence ${icon('chevron')}</button></div>${state.completed?`<div class="card green"><div class="small muted">BEFORE</div><p>${esc(state.service)}</p><div class="divider"></div><div class="small" style="color:var(--green)">AFTER</div><p class="bold">${icon('check')} Drainage cycle completed successfully</p></div><div class="card"><h3>Work completed</h3><p>${scope()}<br>Drainage and leak tests passed</p><div class="info-row"><span>Completed</span><span>${esc(state.finishedAt)}</span></div><div class="info-row"><span>Approved quotation / invoice</span><span>${money(total())} · v${state.approvedRevision}</span></div><button class="link" data-action="invoice">${icon('download')} Download invoice</button></div><div class="card purple"><h3>${icon('shield')} 30-day service warranty</h3><p>Valid until ${warrantyExpiry()}. Covers workmanship${state.selected[1]?' and the replaced hose':''} for the approved scope.</p><button class="link" data-action="help">Get help with this service</button></div>`:`<div class="card"><p>${state.inspectionClosed?'Inspection closed without repair.':'No repair work has been completed.'}</p><p>Inspection fee: ₹249</p>${state.inspectionClosed?`<p>Closed: ${esc(state.finishedAt)}</p>`:''}</div>`}<div class="card">${profile()}</div>${state.completed?`<div class="card center"><h3>Was the issue explained clearly?</h3><p class="muted">How confident do you feel about the explanation?</p><div class="rating" role="group" aria-label="Confidence from 1 to 5">${[1,2,3,4,5].map(n=>`<button data-action="rating:${n}" class="${state.rating===n?'active':''}" aria-pressed="${state.rating===n}">${n}</button>`).join('')}</div><div class="row between tiny muted"><span>Not confident</span><span>Very confident</span></div>${state.rating?'<p class="small" style="color:var(--green)">Thank you. Your feedback is saved.</p>':''}</div>`:''}</div>`;
case 'assigned':footer=button('Start inspection '+icon('chevron'),'go:checklist');return `<div class="page"><div class="row between">${badge('Assigned job','purple')}<span class="tiny muted">UC-WM-28491</span></div><h1 class="page-title" style="margin-top:14px">Washing machine check-up</h1><p class="subtitle">${state.date} · ${state.slot}</p><div class="card"><h3>Rahul Mehta</h3><p>LG front-load washing machine</p><div class="reason"><b>Reported issue</b><br>${esc(state.service)}</div><div class="row start small">${icon('pin')}<span>Flat 402, Palm Heights, Lokhandwala<br>Andheri West, Mumbai · 400053</span></div><div class="inline-btns" style="margin-top:16px">${button(icon('call')+' Call customer','contact:call','secondary')}${button(icon('chat')+' Message','contact:chat','secondary')}</div></div><h3 class="section-title">Reported symptoms</h3><div class="card"><p>${['Water remains inside the drum','Machine displays an error code','Unusual pump noise','Problem started recently'].filter((_,i)=>state.symptoms[i]).map(esc).join('<br>')||'No additional symptoms selected'}</p></div><h3 class="section-title">Service history</h3><div class="card"><p>No previous washing-machine repairs on UC.</p><span class="small muted">First-time appliance repair customer</span></div><div class="card purple"><p>Record your checks and evidence. Share your findings and quote before beginning repair.</p></div></div>`;
case 'checklist':footer=button('Continue to evidence '+icon('chevron'),'go:capture','',!allChecks());return `<div class="page">${step(1)}<h1 class="page-title">Guided inspection</h1><p class="subtitle">Complete each required check. Your notes and evidence help the customer understand the finding.</p><div class="row between small"><b>${state.checkStatus.filter((s,i)=>s&&(s!=='Could not verify'||state.checkReasons[i]?.trim().length>5)).length} of 6 required checks completed</b><span class="muted">Drainage issue</span></div><div class="progress-track"><div style="width:${state.checkStatus.filter(Boolean).length/6*100}%"></div></div>${checks.map((c,i)=>`<div class="card tech-check"><div class="row between"><span class="check-name">${i+1}. ${['Inspect drain filter','Test drain pump output','Inspect outlet hose','Check external drain pipe','Check control-panel error','Test drum rotation'][i]}</span>${state.checkStatus[i]?icon('check','check-icon'):''}</div><div class="segmented">${['Passed','Issue found','Could not verify'].map(t=>`<button class="${state.checkStatus[i]===t?'active':''}" data-action="check:${i}:${t}">${t}</button>`).join('')}</div>${state.checkStatus[i]==='Could not verify'?`<label class="field-label" for="reason-${i}">Why couldn’t this be verified? *</label><input id="reason-${i}" class="field" data-reason="${i}" value="${esc(state.checkReasons[i]||'')}" placeholder="Record a specific reason">`:''}<div class="mini-actions"><button data-action="note:${i}">+ Observation</button><button data-action="upload:${i}:photo">+ Photo</button><button data-action="upload:${i}:video">+ Video</button></div><div class="mini-actions"><button data-action="reading:${i}">+ Reading</button><button data-action="code:${i}">+ Error code</button></div>${state.observations[i]?`<p class="tiny muted">${esc(state.observations[i])}</p>`:''}</div>`).join('')}${!allChecks()?'<div class="warning">Complete all checks, or provide a reason for each unverified check, to continue.</div>':''}</div>`;
case 'capture':footer=button('Record finding '+icon('chevron'),'go:finding','',!allChecks());return `<div class="page">${step(2)}<h1 class="page-title">Make the finding visible</h1><p class="subtitle">Evidence from your inspection, linked to the check it supports. Illustrations represent demo captures.</p>${state.evidence.map((e,i)=>`<div class="card"><div class="row start"><button class="evidence-card" data-action="evidence:${i}" style="width:94px;flex-shrink:0"><div class="evidence-art" style="height:74px">${evidenceArt(e)}</div></button><div class="grow"><b class="small">${esc(e.title)}</b><div class="tiny muted">${esc(checks[e.check][0])}<br>${esc(e.time)} · Captured by Arjun</div>${badge(e.clear?'Quality verified':'Evidence unclear',e.clear?'green':'amber')}</div></div><p>${esc(e.description)}</p><div class="mini-actions"><button data-action="retake:${i}">Retake</button><button data-action="remove:${i}">Remove</button><button data-action="unclear:${i}">${e.clear?'Mark unclear':'Confirm clear'}</button></div></div>`).join('')}${button('+ Add another evidence item','upload:0:photo','secondary')}<div class="trust-note">${icon('info')}<span>Confirm that images are in focus and readings are legible. Unclear evidence blocks sharing a confirmed diagnosis.</span></div></div>`;
case 'finding':footer=button('Draft customer summary '+icon('spark'),'generate','',!allChecks()||state.certaintyReason.trim().length<13);return `<div class="page">${step(3)}<h1 class="page-title">Finding & certainty</h1><p class="subtitle">Record your inspection finding. UC Assist will help explain it to the customer.</p><div class="card"><h3>Main finding</h3><p>${esc(findingText())}</p></div><label class="field-label">How certain is the finding?</label><div class="segmented">${['Confirmed','Likely','Not Verified'].map(t=>`<button class="${state.certainty===t?'active':''}" data-action="certainty:${t}">${t}</button>`).join('')}</div><label class="field-label" for="certaintyReason">Explain your certainty *</label><textarea id="certaintyReason" data-field="certaintyReason">${esc(state.certaintyReason)}</textarea><label class="field-label" for="recommend">Recommended action</label><select id="recommend" data-field="recommend">${['Repair','Monitor and reassess','Additional inspection required','No repair required','Replacement may be more appropriate'].map(t=>`<option ${state.recommend===t?'selected':''}>${t}</option>`).join('')}</select><div class="card ${state.certainty==='Confirmed'?'green':'amber'}"><p>${state.certainty==='Confirmed'?'Confirmed findings need direct inspection, readings or visible evidence.':'Uncertainty must remain visible to the customer. Request additional inspection before recommending unsupported work.'}</p></div></div>`;
case 'summary':footer=button((hasQuote()?'Create evidence-linked quote ':'Review inspection ')+icon('chevron'),hasQuote()?'go:create-quote':'go:review','',!allChecks()||!state.reviewed||!state.summary);return `<div class="page">${step(4)}<h1 class="page-title">A clearer explanation</h1><p class="subtitle">Your inspection. In language the customer can understand.</p><div class="card purple"><div class="assist-header">${icon('spark')} Drafted with UC Assist</div>${badge('Professional certainty: '+state.certainty,state.certainty==='Confirmed'?'green':'amber')}<label class="field-label" for="summary">Customer-friendly summary · Editable</label><textarea id="summary" data-field="summary" style="min-height:175px">${esc(state.summary)}</textarea><button class="link" data-action="generate" style="margin-top:10px">${icon('rotate')} Regenerate from recorded findings</button></div><h3 class="section-title">UC Assist validation</h3><div class="card">${validations().slice(0,6).map(v=>`<div class="validation-row ${v.ok?'':'fail'}">${icon(v.ok?'check':'info')}${v.label}</div>`).join('')}</div><label class="checkbox"><input type="checkbox" id="reviewed" ${state.reviewed?'checked':''}>I have reviewed this summary and confirm that it accurately represents my inspection.</label><div class="trust-note">${icon('shield')}<span>UC Assist summarises and validates. It does not inspect, diagnose, submit or approve the repair.</span></div></div>`;
case 'create-quote':footer=button('Review before sharing '+icon('chevron'),'quote-create','',!allChecks()||!rules.selected(state).length||rules.selected(state).some(i=>!rules.itemSupported(state,i)));return `<div class="page">${step(5)}<h1 class="page-title">Build the repair quote</h1><p class="subtitle">Add work from the UC rate card. Every item needs a finding, check and supporting evidence.</p>${state.certainty!=='Confirmed'?'<div class="warning">These repair items are unsupported for an uncertain finding. Confirm the finding with additional checks before submitting this quote.</div>':''}${quoteItems(true)}${totals()}${rules.selected(state).some(i=>!rules.itemSupported(state,i))?'<div class="warning">Selected items require matching completed checks and clear evidence.</div>':''}<div class="trust-note">${icon('info')}<span>Any change to the scope or price invalidates earlier customer approval.</span></div></div>`;
case 'review':footer=button('Submit to customer '+icon('chevron'),'submit','',!canSubmit());return `<div class="page">${step(6)}<h1 class="page-title">Ready to share?</h1><p class="subtitle">Preview what Rahul will receive. You are responsible for the diagnosis and final summary.</p>${validations().some(v=>!v.ok)?`<div class="card amber"><h3>Resolve before sharing</h3>${validations().filter(v=>!v.ok).map(v=>`<div class="validation-row fail">${icon('info')}${v.label}</div>`).join('')}</div>`:`<div class="status-banner">${icon('check')} All checks passed · Ready for your review</div>`}<div class="row between"><h3 class="section-title">Diagnosis Snapshot</h3><button class="link" data-action="go:finding">Edit diagnosis</button></div>${findingCard()}<p class="small muted">6 checks completed · ${state.evidence.length} evidence items</p>${evidenceCards()}<button class="link" data-action="go:capture" style="margin-top:10px">Edit evidence</button>${assistCard()}<button class="link" data-action="go:summary">Edit explanation</button><div class="row between"><h3 class="section-title">Evidence-Linked Quote</h3><button class="link" data-action="go:create-quote">Edit quotation</button></div>${hasQuote()?quoteItems()+totals():'<div class="card amber"><h3>No repair quotation recommended</h3><p>Recorded recommendation: ${esc(state.recommend)}. No repair quotation is included. The inspection fee is ₹249.</p></div>'}<div class="card"><h3>Customer decision options</h3><p>${hasQuote()?'Approve repair · Request expert review · Decline repair':'Request expert review · Review recorded recommendation'}</p><p class="tiny muted">You cannot begin until the customer approves this quote.</p></div></div>`;
case 'waiting':footer=state.inspectionClosed?button('View customer service record','customer-record','secondary'):rules.canCloseInspection(state)?button('Close inspection · ₹249','close-inspection','secondary'):canRepair()?button(state.repairStarted?'Complete repair':'Start repair',state.repairStarted?'complete':'start-repair'):button('Start repair','start-repair','',true);return `<div class="page">${badge(state.completed?'Repair completed':state.inspectionClosed?'Inspection closed':state.approved?'Repair approved':state.customerStatus==='Declined'?'Repair declined':'Awaiting customer',state.approved||state.completed?'green':'purple')}<h1 class="page-title" style="margin-top:15px">${state.inspectionClosed?'Inspection closed without repair':state.completed?'The job is complete':state.approved?(state.repairStarted?'Repair in progress':'You’re cleared to begin'):'Shared with Rahul'}</h1><p class="subtitle">${state.inspectionClosed?'The findings and ₹249 inspection fee are saved in Rahul’s record.':state.completed?'The service record and invoice are available to Rahul.':state.approved?'Repair approval received for the scope below.':(hasQuote()?'Diagnosis and quotation shared with Rahul. Wait for his decision before starting work.':'Inspection findings shared with Rahul. Recorded recommendation: '+esc(state.recommend)+'. No repair quotation is recommended.')}</p><div class="card"><div class="row between"><h3 style="margin:0">Customer status</h3>${badge(state.customerStatus,state.approved?'green':'purple')}</div><div class="info-row"><span>${hasQuote()?'Shared quotation':'Shared diagnosis'}</span><span>Version ${state.revision}</span></div><div class="info-row"><span>${!hasQuote()?'Next step':state.approved?'Approved amount':'Total amount'}</span><b>${hasQuote()?money(total()):esc(state.recommend)}</b></div>${state.approved?`<div class="divider"></div><p>Approved scope:<br>${scope()}</p>`:''}</div>${clarificationCard()}${state.expert==='pending'?'<div class="card amber"><h3>Expert review requested</h3><p>Wait for the review and fresh customer approval.</p><button class="link" data-action="review-response">Respond to expert review</button></div>':''}${state.repairStarted?`<div class="card green"><h3>Repair started</h3><p>${scope()}<br>Run a drainage and leak test.</p></div>`:''}<div class="card"><h3>Stay available</h3><p>Answer questions and clarify evidence without changing the customer’s decision.</p><div class="mini-actions"><button data-action="contact:chat">Message customer</button><button data-action="clarify">Clarify finding</button></div></div>${hasQuote()&&!state.completed&&!state.repairStarted?button('Revise quotation','revise-modal','secondary'):''}${button('Open customer view '+icon('chevron'),'switch-customer','quiet')}${(state.completed||state.inspectionClosed)?button('View customer service record','customer-record','secondary'):''}<div class="trust-note">${icon('shield')}<span>${state.approved?'If the price or scope changes, this approval is invalidated.':'Only a customer approval enables Start repair.'}</span></div></div>`;
default:return locked();}}
