function invalidate(){draftEpoch++;if(state.submitted)state.previousQuote={total:total(),selected:[...state.selected],prices:[...state.prices]};if(state.submitted||state.approved){state.submitted=false;state.approved=false;state.approvedRevision=null;state.repairStarted=false;state.customerStatus='Not viewed';state.expert='none';state.revision++;toast('Changed inspection: resubmit and obtain fresh approval.')}state.reviewed=false;state.quoteCreated=false;save()}
